INSERT INTO `ai_knowledge` (`title`, `category`, `content`, `tags`, `status`) VALUES
('商城导航与核心功能', 'guide', '用户可以通过首页、分类、购物车、我的订单、个人中心、客服中心、AI小助手等导航进入主要功能。首页包含搜索框、搜索热词、领券中心、秒杀、签到领积分、轮播图、热销商品、新品上市和为你推荐。', '功能,导航,首页,分类,购物车,个人中心,客服,AI小助手', 1),
('账号注册登录与资料管理', 'account', '用户需要先注册再登录。忘记密码时，可以在登录页通过手机号验证码重置密码。个人中心支持商品收藏、浏览记录、券包、积分商城、地址管理、密码管理、关于我们，以及点击头像区域修改个人信息。商城暂不支持注销账号。', '注册,登录,密码,验证码,个人信息,头像,注销,账号', 1),
('商品浏览与评价规则', 'product', '商品详情页展示库存、销量、规格、收藏按钮、加入购物车、立即购买、商品描述、商品评价和5星评级。发布评价需要先购买商品，在我的订单已完成标签下确认收货后点击评价按钮。评价发布后，登录用户可以点赞或评论，评论最多支持二级。', '商品,详情,库存,规格,收藏,评价,点赞,评论', 1),
('下单与支付流程', 'order', '购买前需要先填写收货地址，之后默认使用默认地址，所有商品免运费。用户可以先加入购物车再去结算，也可以在商品详情页点击立即购买。结算页可切换地址、选择商品优惠券或订单券、填写备注，并查看订单原价、优惠金额和最终实付金额。提交订单后会进入我的订单待付款标签，点击去支付会出现支付宝二维码，扫码即可支付。', '购买,下单,支付,购物车,结算,地址,支付宝,二维码,待付款', 1),
('订单取消与确认收货', 'order', '下单后15分钟未支付会自动取消订单，并返还已使用的商品优惠券和订单优惠券。待付款订单用户也可以主动取消。订单状态为待收货且用户已收到商品时，可以点击确认收货，订单状态会变为已完成。已完成后可以点击再次购买，将商品项再次添加到购物车。', '订单,取消,超时,确认收货,待收货,已完成,再次购买', 1),
('退款售后规则', 'refund', '订单已完成且确认收货7天内可以申请退款。申请时退款金额不能大于实付金额，需要填写退款原因，也可以上传图片凭证。提交后状态变为退款申请中，用户可以取消申请。商家同意后会显示实际同意退款金额，用户退回商品后商家完成退款；若无法接受处理结果，可联系人工客服。退款原因不合理时，商家可能拒绝退款。', '退款,售后,退货,凭证,申请退款,商家,拒绝,客服', 1),
('优惠活动与优惠券规则', 'coupon', 'NexMart会不定期举行优惠活动，有活动的商品会在图片左上角显示活动标签，优惠方式包括固定金额减免或折扣。优惠券分为商品优惠券和订单优惠券。商品优惠券可通过领券中心领取，可以与促销活动叠加；订单优惠券作用于整笔订单，优惠力度更大，不支持与优惠活动叠加，一个订单只能使用一张。', '优惠,促销,优惠券,商品券,订单券,领券,折扣,满减', 1),
('积分与签到规则', 'points', '用户可以通过首页签到领积分按钮领取积分，连续签到一定天数可以获得更多积分奖励。积分明细可在查看积分明细中查看。积分可以用于积分商城兑换订单优惠券。', '积分,签到,连续签到,积分商城,兑换,积分明细', 1),
('限时秒杀规则', 'seckill', '限时秒杀是优惠力度较大的活动，用户可以抢购秒杀商品，也可以抢购订单券。秒杀商品和秒杀订单券都有库存限制，并且通常存在每人限购限制。', '秒杀,限时,抢购,库存,限购,订单券', 1),
('人工客服能力', 'customer_service', '客服中心支持发送文本、表情、图片、商品卡片和订单卡片。如果选择商品时没有可选项，说明用户还没有浏览点击任何商品；如果选择订单时没有可选项，说明当前没有订单。客服查看用户消息后会显示已读；用户不在客服中心页面时，客服中心导航栏会出现红色气泡提醒。', '人工客服,客服中心,表情,图片,商品卡片,订单卡片,已读,气泡', 1);
